import json,urllib.parse,urllib.request,pathlib,re,html
u='https://commons.wikimedia.org/w/api.php?'+urllib.parse.urlencode({'action':'query','titles':'File:Sydney Opera House - Dec 2008.jpg','prop':'imageinfo','iiprop':'url|extmetadata','iiurlwidth':1000,'format':'json'})
r=urllib.request.Request(u,headers={'User-Agent':'EduConnect/1.0 (photo attribution)'}); d=json.load(urllib.request.urlopen(r,timeout=20)); p=next(iter(d['query']['pages'].values())); i=p['imageinfo'][0]; m=i['extmetadata']; clean=lambda x:re.sub('<[^>]+>',' ',html.unescape(str(x or ''))).strip(); print(json.dumps({'url':i.get('thumburl'),'sourcePage':i.get('descriptionurl'),'license':clean(m.get('LicenseShortName',{}).get('value')),'licenseUrl':clean(m.get('LicenseUrl',{}).get('value')),'artist':clean(m.get('Artist',{}).get('value')),'description':clean(m.get('ImageDescription',{}).get('value'))},ensure_ascii=False))
